function excuseAction(latValue,lonValue ,storeId)
    local latLon = getEnterStoreLatLon(storeId);
    latValue = string.gsub(latValue,"@luaExtra","")
    lonValue = string.gsub(lonValue,"@luaExtra","")
    local distance = 0
    if latLon ~= "" and latLon ~=nil then
        local param = latValue..","..lonValue..","..latLon
        distance = getDataByMethod("getDistanceBetweenRealAndStore",param);
        distance = string.gsub(distance,"@luaExtra","")
    end
    callQstWidgetMethodByQstCode("outstore_01","setCurrentValueWithPresentation",string.format("%.3f",distance/1000));
    if tonumber(distance) <=300 then
        callQstWidgetMethodByQstCode("outstore_06","setWidgetHidden","true");
        callQstWidgetMethodByQstCode("outstore_06","setRequest","false");
    else
        callQstWidgetMethodByQstCode("outstore_06","setWidgetHidden","false");
        callQstWidgetMethodByQstCode("outstore_06","setRequest","true");
        setTip("离店偏差进店GPS定位大于300米，请填写原因！")
        return
    end
end

