function setValue()
    setUploadButtonHidden("true")
    local enterTime = getEnterStoreTime();
    local exitTime = getExitStoreTime();
    local durTime = getDurationStoreTime();
    callQstWidgetMethodByQstName("进店时间","setCurrentValueWithPresentation:",enterTime);
    callQstWidgetMethodByQstName("离店时间","setCurrentValueWithPresentation:",exitTime);
    callQstWidgetMethodByQstName("在店时间","setCurrentValueWithPresentation:",durTime);
    local id = getCurStoreInfoByParam("_id");
    local curId=getDataByMethod("executeSql:","select _id from base_store_visitplan where store_id='"..id.."'");
    if curId ~= "" then
        local pos = string.find(curId, "|");
        curId = string.sub(curId, 1, pos - 1);
        pos = string.find(curId, "@");
        curId = string.sub(curId, 1, pos - 1);
        pos = string.find(curId, ",");
        curId = string.sub(curId, pos + 1, #curId);
        time = getDataByMethod("getCurrentDate","")
        empid = getDataByMethod("getEmpId","")
        local maxId=getDataByMethod("executeSql:","select max(_id) as id from base_store_visitplan where emp_id='"..empid.."' and biz_date='"..time.."'");
        if maxId ~= "" then
            pos = string.find(maxId, "|");
            maxId = string.sub(maxId, 1, pos - 1);

            pos = string.find(maxId, "@");
            maxId = string.sub(maxId, 1, pos - 1);

            pos = string.find(maxId, ",");
            maxId = string.sub(maxId, pos + 1, #maxId);
            if curId == maxId then
                callQstWidgetMethodByQstCode("cldc","setRequest:",true);
                callQstWidgetMethodByQstCode("cldc","setWidgetHidden:","false");
            end
        end
    end
end
