        local position = string.find(newTableValue, ",")
        local dictName1 = string.sub(newTableValue, 1, position - 1)

        local kamemoValue =  string.gsub(memo,"null","");
        local position_memo = string.find(kamemoValue, ",")
        local forenoon_memo = string.sub(kamemoValue, 1, position_memo - 1)
        if dictName1 ~= "" then
            local dictId = callQstWidgetMethodByQstCode("wt_kaoqinbg","callGridMethodWithParams:","[@][@]getProdIdByName[@]"..dictName1);
            callQstWidgetMethodByQstCode("wt_kaoqinbg","callGridMethodWithParams:",dictId.."[@]col1[@]setValue[@]1");
