                callQstWidgetMethodByQstCode("wt_kaoqinbg","callGridMethodWithParams:",dictId.."[@]col4[@]setValue[@]"..forenoon_memo);
            end
        end
        local dictName2 = string.sub(newTableValue, position+1,#newTableValue);
        local aforenoon_memo = string.sub(kamemoValue, position_memo+1, #kamemoValue)
        if dictName2 ~= "" then
