                callQstWidgetMethodByQstCode("wt_kaoqinbg","callGridMethodWithParams:",dictId.."[@]col4[@]setValue[@]"..aforenoon_memo);
            end
            if  dictName1 == dictName2 then
                callQstWidgetMethodByQstCode("wt_kaoqinbg","callGridMethodWithParams:",dictId.."[@]col3[@]setValue[@]1");
            end
        end
    end
